Here is the commit message:
can: ucan: Fix infinite loop from zero-length messages

If a broken ucan device gets a message with the message length field set
to 0, then the driver will loop for forever in
ucan_read_bulk_callback(), hanging the system.  If the length is 0, just
skip the message and go on to the next one.

This has been fixed in the kvaser_usb driver in the past in commit
0c73772cd2b8 ("can: kvaser_usb: leaf: Fix potential infinite loop in
command parsers"), so there must be some broken devices out there like
this somewhere.

Cc: Marc Kleine-Budde <mkl@pengutronix.de>
Cc: Vincent Mailhol <mailhol@kernel.org>
Cc: stable@kernel.org
Assisted-by: gkh_clanker_2000
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>
Link: https://patch.msgid.link/2026022319-huff-absurd-6a18@gregkh
Fixes: 9f2d3eae88d2 ("can: ucan: add driver for Theobroma Systems UCAN devices")
Signed-off-by: Marc Kleine-Budde <mkl@pengutronix.de>

Here is the root cause:
The loop processing incoming messages from the USB CAN device in `ucan_read_bulk_callback()` did not check for a message length of zero. When a broken device sends a message with `len == 0`, the loop fails to advance the buffer position (`pos`), causing it to repeatedly process the same zero-length message indefinitely, resulting in a system hang.

Here is the patch:
 /* callback on reception of a USB message */
 static void ucan_read_bulk_callback(struct urb *urb)
 {
 	int ret;
 	int pos;
 	struct ucan_priv *up = urb->context;
 	struct net_device *netdev = up->netdev;
 	struct ucan_message_in *m;

 	/* the device is not up and the driver should not receive any
 	 * data on the bulk in pipe
 	 */
 	if (WARN_ON(!up->context_array)) {
 		usb_free_coherent(up->udev,
 				  up->in_ep_size,
 				  urb->transfer_buffer,
 				  urb->transfer_dma);
 		return;
 	}

 	/* check URB status */
 	switch (urb->status) {
 	case 0:
 		break;
 	case -ENOENT:
 	case -EPIPE:
 	case -EPROTO:
 	case -ESHUTDOWN:
 	case -ETIME:
 		/* urb is not resubmitted -> free dma data */
 		usb_free_coherent(up->udev,
 				  up->in_ep_size,
 				  urb->transfer_buffer,
 				  urb->transfer_dma);
 		netdev_dbg(up->netdev, "not resubmitting urb; status: %d\n",
 			   urb->status);
 		return;
 	default:
 		goto resubmit;
 	}

 	/* sanity check */
 	if (!netif_device_present(netdev))
 		return;

 	/* iterate over input */
 	pos = 0;
 	while (pos < urb->actual_length) {
 		int len;

 		/* check sanity (length of header) */
 		if ((urb->actual_length - pos) < UCAN_IN_HDR_SIZE) {
 			netdev_warn(up->netdev,
 				    "invalid message (short; no hdr; l:%d)\n",
 				    urb->actual_length);
 			goto resubmit;
 		}

 		/* setup the message address */
 		m = (struct ucan_message_in *)
 			((u8 *)urb->transfer_buffer + pos);
 		len = le16_to_cpu(m->len);

 		/* check sanity (length of content) */
-		if (urb->actual_length - pos < len) {
+		if ((len == 0) || (urb->actual_length - pos < len)) {
 			netdev_warn(up->netdev,
 				    "invalid message (short; no data; l:%d)\n",
 				    urb->actual_length);
 			print_hex_dump(KERN_WARNING,
 				       "raw data: ",
 				       DUMP_PREFIX_ADDRESS,
 				       16,
 				       1,
 				       urb->transfer_buffer,
 				       urb->actual_length,
 				       true);

 			goto resubmit;
 		}

 		switch (m->type) {
 		case UCAN_IN_RX:
 			ucan_rx_can_msg(up, m);
 			break;
 		case UCAN_IN_TX_COMPLETE:
 			ucan_tx_complete_msg(up, m);
 			break;
 		default:
 			netdev_warn(up->netdev,
 				    "invalid message (type; t:%d)\n",
 				    m->type);
 			break;
 		}

 		/* proceed to next message */
 		pos += len;
 		/* align to 4 byte boundary */
 		pos = round_up(pos, 4);
 	}

 resubmit:
 	/* resubmit urb when done */
 	usb_fill_bulk_urb(urb, up->udev,
 			  usb_rcvbulkpipe(up->udev,
 					  up->in_ep_addr),
 			  urb->transfer_buffer,
 			  up->in_ep_size,
 			  ucan_read_bulk_callback,
 			  up);

 	usb_anchor_urb(urb, &up->rx_urbs);
 	ret = usb_submit_urb(urb, GFP_ATOMIC);

 	if (ret < 0) {
 		netdev_err(up->netdev,
 			   "failed resubmitting read bulk urb: %d\n",
 			   ret);

 		usb_unanchor_urb(urb);
 		usb_free_coherent(up->udev,
 				  up->in_ep_size,
 				  urb->transfer_buffer,
 				  urb->transfer_dma);

 		if (ret == -ENODEV)
 			netif_device_detach(netdev);
 	}
 }



